1	/**
2	 * `?match08=1` — Screen 08 approved-picture test (2026-11-17, qa/match/08/NOTES.md).
3	 * REAL 3D proxy geometry of the Final Spin Chamber, solved from the user's approved Screen 08 and the locked game
4	 * camera (tools/match08/fit_proxies.py → assets/textures/match08/proj08.json): inlet pipe, gold arch, chamber walls,
5	 * door wall, floor/river plane, platform (top tilted toward the camera as painted), towel and the four half-dome spouts.
6	 * Every surface is textured by camera projection of the CLEAN environment-only artwork (Benny, HUD, coins removed;
7	 * qa/imageblaster/08/) from that locked camera, so the locked view shows the approved scenery and a moving camera sees
8	 * it on geometry (parallax). Surfaces the projector cannot see (behind props) get a plain fallback colour instead of
9	 * a smeared copy (projector depth test). The shader undoes the game's post chain (PROJ05_INVERSE) and takes no fog.
10	 * Without the switch nothing in this file runs and the game is unchanged.
11	 */
12	import * as THREE from 'three';
13	import { PROJ05_INVERSE, flag05 } from '../vfx/waterRibbon';
14	
15	interface Layout {
16	  camera: { matrixWorld: number[]; fov: number; size: [number, number] };
17	  floorY: number;
18	  chamber: { cx: number; cy: number; r: number; zBack: number; zDoor: number };
19	  arch: { z: number; outer: { cx: number; cy: number; r: number }; inner: { cx: number; cy: number; r: number }; depth: number };
20	  pipe: { cx: number; cy: number; r: number; z0: number; z1: number };
21	  backwall: { z: number; holeR: number };
22	  platform: { cx: number; cz: number; r: number; topY: number; rimBottomY: number; floorY: number; tiltDeg: number };
23	  towel: { cx: number; cz: number; w: number; h: number; y0: number; d: number };
24	  spouts: Record<string, { c: [number, number, number]; rx: number; ry: number }>;
25	}
26	
27	export interface Match08 {
28	  group: THREE.Group;
29	  /** the approved picture's splash ring around Benny (camera-facing card; Game places it at Benny + splashOffset) */
30	  splash: THREE.Mesh;
31	  splashOffset: THREE.Vector3;
32	  /** render the projector depth map once (needs the renderer); call after the group is in the scene */
33	  bakeDepth(renderer: THREE.WebGLRenderer): void;
34	  /** live post values for the inverse (exposure from the renderer, render size for the vignette inverse) */
35	  sync(renderer: THREE.WebGLRenderer, w: number, h: number): void;
36	}
37	
38	const VERT = /* glsl */ `
39	uniform mat4 uProjVP;
40	varying vec4 vProj;
41	varying vec3 vW;
42	varying vec3 vN;
43	void main() {
44	  vec4 wp = modelMatrix * vec4(position, 1.0);
45	  vProj = uProjVP * wp;
46	  vW = wp.xyz;
47	  vN = normalize(mat3(modelMatrix) * normal);
48	  gl_Position = projectionMatrix * viewMatrix * wp;
49	}`;
50	
51	const FRAG = /* glsl */ `
52	uniform sampler2D uPlate;
53	uniform sampler2D uDepth;
54	uniform float uUseDepth;
55	uniform vec2 uNearFar;
56	uniform vec3 uFallback;
57	uniform sampler2D uPatch;   // material patch cut from the approved artwork (wall slots / gold band / towel)
58	uniform float uPatchK;      // patch repeats per world unit
59	uniform vec3 uProjPos;      // projector (approved view) position
60	uniform vec4 uPjPost;
61	uniform vec2 uPjRes;
62	uniform sampler2D uFill;    // m08fill: world-anchored wall tile cut from the picture's near pipe wall (unwrap08.py)
63	uniform float uFillMode;    // 0 off (triplanar patch), 1 drum wall (around the chamber axis), 2 flat disc (x/y)
64	uniform vec2 uFillSize;     // tile size in world units (around, along)
65	uniform vec3 uDrum;         // chamber axis x, y and radius
66	uniform mat4 uProjVP;
67	uniform float uSwim;        // m08swim (floor only): the painted river's banks spread to cover Benny's whole swim lane
68	uniform sampler2D uRiv;     // 64 x 1: painted river centre x (r) and full width (g) along z
69	uniform vec4 uRivZ;         // z at texel 0, z at texel 63, lane half-width to cover, floor y
70	uniform sampler2D uOcc;     // m08occ (door wall only): plate with towel + platform painted out (occ08.py), alpha = usable
71	uniform float uOccOn;
72	uniform sampler2D uTMask;   // m08towelm (towel only): the painted towel's outline in plate coordinates (towelmask08.py)
73	uniform float uTMaskOn;
74	uniform vec4 uClipIn;       // m08far collar only: discard inside this x/y circle (the chamber's cross-section) ...
75	uniform vec4 uClipOut;      // ... and outside this one (the pushed arch's outline); w > 0.5 = on
76	uniform vec4 uCeil;         // m08ceil (door wall only): painted door centre x, y on the door plane, plane z, w > 0.5 = on
77	uniform vec4 uCeilW;        // m08ceil source window: angle start, angle width (rad), radius band start, end (world u)
78	uniform sampler2D uRingT;   // m08ring: periodic slot-ring tile (ring08.py): u = angle, v = radius (repeat-wrapped)
79	uniform vec4 uRing;         // m08ring: angle start, angle period (rad), radius start, radius period (u)
80	uniform float uRingOn;
81	uniform vec2 uCeilD;        // m08drum (chamber drum only): x > 0.5 = on, y = fade length (u) from the door plane toward the arch
82	uniform sampler2D uNearT;   // m08near (floor only): crisp near-river tile from the approved picture's own near band (near08.py)
83	uniform vec4 uNear;         // z at tile v = 0, world length of one tile period along the river, tile lateral half range A, w > 0.5 = on
84	uniform vec4 uNearM;        // projection magnification ramp start / end, lateral fade start / end (|lane position|, 1 = bank)
85	uniform vec2 uNearC;        // tile a of the lane centre and of the half lane (the painted water incl. foam spans c +- h)
86	uniform vec4 uCup;          // m08cup (spout cups only): cup centre xyz, w > 0.5 = on
87	uniform vec3 uCupM;         // m08cup mirror plane normal (horizontal, perpendicular to the projector's view of the cup)
88	varying vec4 vProj;
89	varying vec3 vW;
90	varying vec3 vN;
91	${PROJ05_INVERSE}
92	// triplanar, mirrored-repeat sampling of the patch: surfaces the approved picture never showed (or showed edge-on)
93	vec3 patchColor() {
94	  vec3 n = abs(normalize(vN)); n /= max(n.x + n.y + n.z, 1e-4);
95	  vec3 p = vW * uPatchK;
96	  return texture2D(uPatch, p.zy).rgb * n.x + texture2D(uPatch, p.xz).rgb * n.y + texture2D(uPatch, p.xy).rgb * n.z;
97	}
98	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
99	vec3 fillColor() {
100	  vec2 q;
101	  if (uFillMode < 1.5) {
102	    // angle from straight down: the wrap of atan lies under the floor, never seen
103	    float a = atan(vW.x - uDrum.x, -(vW.y - uDrum.y));
104	    float n = floor(6.2831853 * uDrum.z / uFillSize.x + 0.5);  // whole tiles around the drum: no seam
105	    q = vec2(a / 6.2831853 * n, vW.z / uFillSize.y);
106	  } else q = vW.xy / uFillSize;
107	  return texture2D(uFill, q).rgb;
108	}
109	// m08ceil: the painted end wall is concentric around the door (chrome rim, gold bulb ring, slot rows), so a door-wall point
110	// the approved view could not see (behind the arch ring: the ceiling above the door) takes the user's pixels from the SAME
111	// radius in a clean window of the painted wall beside the door (left of the door, between the spout cup and its stream),
112	// repeated (mirrored, a whole number of times around) by angle; beyond the window's slot band the slot rows repeat outward.
113	// The rings therefore continue across the old seam instead of meeting a generic tile.
114	vec3 ceilColorAt(vec2 pxy) {
115	  vec2 d = pxy - uCeil.xy;
116	  float r = length(d), a = atan(d.y, d.x);
117	  float fu = mod((a - uCeilW.x) / uCeilW.y, 2.0);
118	  float as = uCeilW.x + (fu < 1.0 ? fu : 2.0 - fu) * uCeilW.y;
119	  float rs = r;
120	  if (r > uCeilW.w) { float w2 = uCeilW.w - uCeilW.z, fr = mod(r - uCeilW.w, 2.0 * w2); rs = fr < w2 ? uCeilW.w - fr : uCeilW.z + (fr - w2); }
121	  vec4 q = uProjVP * vec4(uCeil.xy + rs * vec2(cos(as), sin(as)), uCeil.z, 1.0);
122	  vec3 c = texture2D(uPlate, q.xy / q.w * 0.5 + 0.5).rgb;
123	  // m08ring (r12): the slot band and beyond repeat the same window PERIODICALLY (no mirror lines -> no chevrons / diamonds);
124	  // explicit gradients from the continuous point (the atan wrap would break the implicit mip selection)
125	  vec2 ex = dFdx(pxy), ey = dFdy(pxy);
126	  float r2 = max(r * r, 1e-6), r1 = max(r, 1e-3);
127	  vec2 gx = vec2((d.x * ex.y - d.y * ex.x) / r2 / uRing.y, dot(d, ex) / r1 / uRing.w);
128	  vec2 gy = vec2((d.x * ey.y - d.y * ey.x) / r2 / uRing.y, dot(d, ey) / r1 / uRing.w);
129	  vec3 rc = textureGrad(uRingT, vec2((a - uRing.x) / uRing.y, (r - uRing.z) / uRing.w), gx, gy).rgb;
130	  return mix(c, rc, uRingOn * smoothstep(uCeilW.z, uCeilW.z + 0.15, r));
131	}
132	vec3 riv(float z) {
133	  float f = clamp((z - uRivZ.x) / (uRivZ.y - uRivZ.x), 0.0, 1.0) * 63.0;
134	  float i0 = floor(f);
135	  vec3 a = texture2D(uRiv, vec2((i0 + 0.5) / 64.0, 0.5)).rgb, b = texture2D(uRiv, vec2((min(i0 + 1.0, 63.0) + 0.5) / 64.0, 0.5)).rgb;
136	  return mix(a, b, f - i0);
137	}
138	// m08swim: lateral remap of a floor point. The middle of the painted river stays as painted, its banks (water edge,
139	// foam) are spread out to the lane half-width, the floor beyond is pushed out and eased back over 2.5 u. World-anchored
140	// (depends on the floor point only) and faded in with the camera's distance from the approved viewpoint.
141	vec3 swimRemap(vec3 w, float mv) {
142	  vec3 r = riv(w.z);
143	  // (b > 0, m08rw only: a wider lane to cover near the camera, where the painted gold arch legs hug the banks)
144	  float hp = 0.5 * r.y, h = mix(hp, max(hp, r.z > 0.0 ? r.z : uRivZ.z), mv);
145	  if (h <= hp + 1e-3) return w;
146	  float d = w.x - r.x, ad = abs(d), a = 0.45 * hp, e = h - hp, o;
147	  if (ad <= a) o = ad;
148	  else if (ad <= h) o = a + (ad - a) * (hp - a) / (h - a);
149	  else o = ad - e * max(0.0, 1.0 - (ad - h) / 2.5);
150	  return vec3(r.x + sign(d) * o, w.y, w.z);
151	}
152	void main() {
153	  if (uClipIn.w > 0.5 && (distance(vW.xy, uClipIn.xy) < uClipIn.z || distance(vW.xy, uClipOut.xy) > uClipOut.z)) discard;
154	  // m08towelm: the towel proxy is cut to the painted towel's outline (the depth bake does the same, so the door wall
155	  // behind receives the window pixels that the rectangle used to carry at towel depth)
156	  if (uTMaskOn > 0.5 && vProj.w > 0.0 && texture2D(uTMask, vProj.xy / vProj.w * 0.5 + 0.5).r < 0.5) discard;
157	  // m08fill fades in as the camera leaves the approved viewpoint (the approved view keeps its exact old pixels)
158	  vec3 pc = patchColor();
159	  if (uFillMode > 0.5) pc = mix(pc, fillColor(), smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
160	  if (uCeil.w > 0.5) pc = mix(pc, ceilColorAt(vW.xy), smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
161	  // m08drum: a drum point the approved view could not see (the top corners next to the door, behind the arch ring) continues
162	  // the SAME painted rings as the door wall: the projector ray through it is followed to the door plane and coloured there
163	  // as m08ceil colours the door wall (identical at the drum / door-wall junction, so no seam); fades out toward the arch
164	  if (uCeilD.x > 0.5) {
165	    vec3 dp = uProjPos + (vW - uProjPos) * ((uCeil.z - uProjPos.z) / (vW.z - uProjPos.z));
166	    float wz = 1.0 - smoothstep(uCeil.z + 0.5 * uCeilD.y, uCeil.z + uCeilD.y, vW.z);
167	    pc = mix(pc, ceilColorAt(dp.xy), wz * smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
168	  }
169	  vec3 t = pc;
170	  // stretch guard: the projection is used where the current view sees the surface no more face-on than the approved
171	  // view did (ratio of the two incidence cosines); in the approved view itself the ratio is 1 -> pure projection
172	  vec3 nn = normalize(vN);
173	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
174	  float keep = 1.0 - smoothstep(2.5, 6.0, cc / max(cp, 1e-3));
175	  vec4 pj = vProj;
176	  float pw = 0.0;  // weight of the direct projection in t (m08cup fills the rest from the cup's mirrored side)
177	  if (uSwim > 0.5) {
178	    float ms = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
179	    if (ms > 0.0) pj = uProjVP * vec4(swimRemap(vW, ms), 1.0);
180	  }
181	  if (pj.w > 0.0) {
182	    vec3 ndc = pj.xyz / pj.w;
183	    vec2 uv = ndc.xy * 0.5 + 0.5;
184	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
185	      float vis = 1.0;
186	      if (uUseDepth > 0.5) {
187	        float zf = linZ(ndc.z * 0.5 + 0.5);
188	        float zs = linZ(texture2D(uDepth, uv).r);
189	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
190	        // m08fill: once the camera has left the approved viewpoint, a soft hand-over to the fill (5 x 5 taps over ~3 %
191	        // of the frame) instead of a hard shadow line; at the viewpoint itself the exact single-tap test (view unchanged)
192	        float mv = uFillMode > 0.5 ? smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)) : 0.0;
193	        if (mv > 0.0) {
194	          float sv = 0.0;
195	          for (int i = -2; i <= 2; i++) for (int j = -2; j <= 2; j++) {
196	            float zt = linZ(texture2D(uDepth, uv + vec2(float(i), float(j) * 0.5625) * 0.007).r);
197	            sv += 1.0 - smoothstep(0.015 * zt, 0.04 * zt + 0.05, zf - zt);
198	          }
199	          vis = mix(vis, smoothstep(0.0, 1.0, sv / 25.0), mv);
200	        }
201	      }
202	      // m08occ: what the approved view could not see behind the towel / platform comes from the occlusion plate (the
203	      // painted door / window continued), not from the fallback tile with its straight edges; off the viewpoint only
204	      vec3 base = pc;
205	      if (uOccOn > 0.5) {
206	        vec4 oc = texture2D(uOcc, uv);
207	        base = mix(pc, oc.rgb, oc.a * smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
208	      }
209	      t = mix(base, texture2D(uPlate, uv).rgb, vis * keep);
210	      pw = vis * keep;
211	    }
212	  }
213	  // m08cup: the cups are round (rotationally symmetric), so a cup point the approved view could not see (its top hidden
214	  // behind the gold arch, or its outer part beyond the picture's edge) takes the painted pixels of its mirror point
215	  // across the vertical plane through the cup axis and the projector; off the approved viewpoint only
216	  if (uCup.w > 0.5) {
217	    float mc = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
218	    // (r12: turning the hidden point about the cup axis instead (+-45 / +-90 deg) put wall pixels on the cup top: the
219	    // proxy dome is taller than the painted cup -> mirror only)
220	    vec3 wm = vW - 2.0 * dot(vW - uCup.xyz, uCupM) * uCupM;
221	    vec4 pm = uProjVP * vec4(wm, 1.0);
222	    if (mc > 0.0 && pw < 0.999 && pm.w > 0.0) {
223	      vec3 nd = pm.xyz / pm.w;
224	      vec2 um = nd.xy * 0.5 + 0.5;
225	      if (um.x >= 0.0 && um.x <= 1.0 && um.y >= 0.0 && um.y <= 1.0) {
226	        float zf = linZ(nd.z * 0.5 + 0.5), zs = linZ(texture2D(uDepth, um).r);
227	        float vm = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
228	        t = mix(t, texture2D(uPlate, um).rgb, vm * (1.0 - pw) * mc);
229	      }
230	    }
231	  }
232	  // m08near: where the moving camera sees the floor projection magnified (it shows plate pixels the approved view saw far
233	  // away and small: smeared streaks), the crisp painted near river takes over, world-anchored along the painted river
234	  // (lateral = position across the swim lane, banks on the painted foam fringe; along = repeating with z). Off the
235	  // approved viewpoint only (approved view unchanged).
236	  if (uNear.w > 0.5) {
237	    // (measured on the plain projection: the swim remap is piecewise, its kinks would make the hand-over jump)
238	    vec2 pu = vProj.xy / max(vProj.w, 1e-4) * 0.5 * uPjRes;
239	    float det = abs(dFdx(pu).x * dFdy(pu).y - dFdx(pu).y * dFdy(pu).x);
240	    float mag = vProj.w > 0.0 ? inversesqrt(max(det, 1e-8)) : 99.0;
241	    float mn = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
242	    vec3 r = riv(vW.z);
243	    float hp = 0.5 * r.y, h = mix(hp, max(hp, uRivZ.z), mn);
244	    float sl = (vW.x - r.x) / h;
245	    vec2 tuv = vec2(0.5 + (uNearC.x + uNearC.y * sl) / (2.0 * uNear.z), (uNear.x - vW.z) / uNear.y);
246	    float wn = mn * smoothstep(uNearM.x, uNearM.y, mag) * (1.0 - smoothstep(uNearM.z, uNearM.w, abs(sl)));
247	    if (wn > 0.0) t = mix(t, texture2D(uNearT, tuv).rgb, wn);
248	  }
249	  gl_FragColor = vec4(pjInverse(t), 1.0);
250	}`;
251	
252	/** several (nu × nv) vertex grids f(u, v) → one indexed geometry (m08arch: fine tessellation for per-vertex pushes) */
253	function gridGeo(parts: [number, number, (u: number, v: number) => THREE.Vector3][]): THREE.BufferGeometry {
254	  const pos: number[] = [], idx: number[] = [];
255	  for (const [nu, nv, f] of parts) {
256	    const b = pos.length / 3;
257	    for (let j = 0; j <= nv; j++) for (let i = 0; i <= nu; i++) { const p = f(i / nu, j / nv); pos.push(p.x, p.y, p.z); }
258	    for (let j = 0; j < nv; j++) for (let i = 0; i < nu; i++) { const a = b + j * (nu + 1) + i, c = a + nu + 1; idx.push(a, c, a + 1, c, c + 1, a + 1); }
259	  }
260	  const g = new THREE.BufferGeometry();
261	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setIndex(idx); g.computeVertexNormals();
262	  return g;
263	}
264	
265	export async function buildMatch08(): Promise<Match08> {
266	  const L: Layout = await fetch(new URL('../../assets/textures/match08/proj08.json', import.meta.url).href).then((r) => r.json());
267	  const plate = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/plate08_hybrid.png', import.meta.url).href);
268	  plate.colorSpace = THREE.NoColorSpace; // raw display values: the shader inverts the post chain itself
269	  plate.minFilter = THREE.LinearMipmapLinearFilter;
270	  plate.anisotropy = 8;
271	
272	  // the projector = the locked game camera the picture was matched to
273	  const [W, H] = L.camera.size;
274	  const proj = new THREE.PerspectiveCamera(L.camera.fov, W / H, 0.2, 160);
275	  proj.matrixWorld.fromArray(L.camera.matrixWorld);
276	  proj.matrixWorld.decompose(proj.position, proj.quaternion, proj.scale);
277	  proj.matrixWorldInverse.copy(proj.matrixWorld).invert();
278	  proj.updateProjectionMatrix();
279	  const projVP = new THREE.Matrix4().multiplyMatrices(proj.projectionMatrix, proj.matrixWorldInverse);
280	
281	  const depthRT = new THREE.WebGLRenderTarget(1024, Math.round((1024 * H) / W), { depthBuffer: true });
282	  depthRT.depthTexture = new THREE.DepthTexture(depthRT.width, depthRT.height, THREE.UnsignedIntType);
283	  const shared = {
284	    uPlate: { value: plate },
285	    uDepth: { value: depthRT.depthTexture as THREE.Texture },
286	    uUseDepth: { value: 0 },
287	    uNearFar: { value: new THREE.Vector2(proj.near, proj.far) },
288	    uProjVP: { value: projVP },
289	    uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) },
290	    uPjRes: { value: new THREE.Vector2(W, H) },
291	    uProjPos: { value: proj.position.clone() },
292	  };
293	  // material patches cut from the approved artwork (tools: qa/match/08/NOTES.md), mirrored so the tiling has no seams
294	  const loadPatch = async (name: string) => {
295	    const t = await new THREE.TextureLoader().loadAsync(new URL(`../../assets/textures/match08/patch_${name}.png`, import.meta.url).href);
296	    t.colorSpace = THREE.NoColorSpace; t.wrapS = t.wrapT = THREE.MirroredRepeatWrapping; t.anisotropy = 4; return t;
297	  };
298	  const [pWall, pGold, pTowel] = await Promise.all([loadPatch('wall'), loadPatch('gold'), loadPatch('towel')]);
299	  // `&m08fill=1` (scenery round): chamber surfaces the picture never showed get a world-anchored tile of the picture's
300	  // own wall (no mirrored kaleidoscope); see tools/match08/unwrap08.py and qa/match/08/scenery/NOTES.md
301	  const fill = flag05('m08fill');
302	  let fillTex: THREE.Texture | null = null, fillSize = new THREE.Vector2(1, 1);
303	  if (fill) {
304	    const FJ: { w: number; h: number } = await fetch(new URL('../../assets/textures/match08/fill_drum.json', import.meta.url).href).then((r) => r.json());
305	    fillTex = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/fill_drum.png', import.meta.url).href);
306	    fillTex.colorSpace = THREE.NoColorSpace; fillTex.wrapS = fillTex.wrapT = THREE.RepeatWrapping; fillTex.anisotropy = 8;
307	    // `&m08seam=1` (r6): the tile came from the NEAR pipe wall; on the chamber drum its slots looked denser than the painted
308	    // chamber wall beside them (a visible slot-size change at the hand-over) -> scale the tile (×m08seamk, default 1.6)
309	    const seamK = flag05('m08seam') ? Number(new URLSearchParams(location.search).get('m08seamk') ?? '') || 1.6 : 1;
310	    fillSize = new THREE.Vector2(FJ.w * seamK, FJ.h * seamK);
311	  }
312	  // `&m08swim=1` (scenery round r6): Benny can steer ±2.22 u (+ his body) off the course centre, but the painted river is
313	  // only 2–4 u wide over the first 8 u of the chamber, so hard steering put him on the purple floor. The floor material
314	  // spreads the painted river's banks to the whole reachable lane (river08.json centre / width), approved view unchanged.
